source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # The pattern shifts back by one place at and to the right of each row's diagonal.
    base = []
    for c in range(w):
        counts = {}
        for r in range(c + 1, h):
            v = grid[r][c]
            if v:
                counts[v] = counts.get(v, 0) + 1
        if counts:
            base.append(max(counts, key=counts.get))
        else:
            base.append(None)
    known = [v for v in base if v is not None]
    lo, hi = min(known), max(known)
    for c, v in enumerate(base):
        if v is None:
            prev = base[c-1]
            base[c] = (lo if prev == hi else prev + 1)
    def preceding(v):
        return hi if v == lo else v - 1
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            expected = base[c] if c < r else (preceding(base[c-1]) if c == 0 else base[c-1])
            row.append(grid[r][c] if grid[r][c] else expected)
        out.append(row)
    return out
'''
